       assert(isAbsolute(`d:\`));
       assert(isAbsolute(`d:\foo`));
       assert(isAbsolute(`\\foo\bar`));
       assert(!isAbsolute(`\`));
       assert(!isAbsolute(`\foo`));
       assert(!isAbsolute("d:foo"));
